pub mod gunbc_ci {
    //! `gunbc.ci` workflow gate selection — **Layer 1** affected-set dispatch substrate.
    //!
    //! **Authority** (Phase B): `docs/briefs/r3-wave1-s6-slice7-affected-set-impl-worker.md`;
    //! fail-closed behavior aligned with
    //! `docs/design-t-wad-slice-7-binary-shim-affected-set-selection-canvas.md` §3 (superset
    //! table) applied to **gate-id** touch seeds (see §4 for how end-state runners join
    //! `NodeRef` / dimension receipts to obligations — **not implemented in this module**);
    //! carrier shape: `dsl/gunbc/ci.dag` (`CIWorkflowDag`, `CIGateEdge`: `from` is a prerequisite of `to`).
    //!
    //! **Layer 1 vs canvas §7 / ROADMAP gate #103:** program row `ci_uses_affected_set_selection`
    //! eventually requires the Slice-5 **BinaryShim** runner to wire PR #2713 affected-set
    //! receipts through `CIWorkflowDag` / `TestClaim` metadata (canvas §§1.1–1.3, §4, §7).
    //! This crate surface **does not** close that hand-off: there is no typed PR #2713
    //! receipt type here and no runner entry mapping `Set<NodeRef>` into these APIs.
    //! What lands here is the **pure graph planner** — [`select_affected_gates`] — plus a
    //! thin [`CiBinaryShimAffectedSetReceipt`] adapter for **gate-id seeds only** (tests +
    //! future runner glue once upstream produces `CIGate.id` touches).
    //!
    //! This module is intentionally **pure**: every decision is a function of
    //! [`CiWorkflowDagInput`] + [`CiWorkflowDiff`] only. Git diffs, path-regex, env,
    //! and PR #2713 lens output must be **mapped upstream** into [`CiWorkflowDiff`] (or a
    //! superset-equivalent touch set) before calling [`select_affected_gates`].
    //!
    //! **Verifier ratchet witness (Phase C scaffolding)** — `docs/design-ci-workflow-substrate-shape-2026-05-12.md`
    //! S5 + prequeue §5.2: monotone **inclusion** under enlarging the touched-id
    //! set (smaller touch ⊆ larger touch ⇒ selected subset ⊆ selected superset).
    //! See [`selection_subset_under_touch_set_growth`].
    //!
    //! **Expansion semantics:** [`select_affected_gates`] walks each `CIGateEdge` **symmetrically**
    //! (treat `from → to` as an undirected adjacency) to fixpoint, so a downstream obligation
    //! pulls in its sibling prerequisites (e.g. touching `lint` selects `l1-ratchet`, which
    //! forces `tests` because both parents are prerequisites of `l1-ratchet`). The returned
    //! order is a **topological sort** of that vertex set on the directed prerequisite subgraph.
    //!
    //! **Global carrier validity:** before expanding any touch seed, [`select_affected_gates`] requires
    //! the **entire** directed prerequisite graph on [`CiWorkflowDagInput::gates`] to be acyclic. A cycle
    //! confined to an unselected weak component must still fail closed (P3), not succeed in “narrow” mode.

    use std::collections::{BTreeSet, HashMap, HashSet, VecDeque};

    /// Structural mirror of `CIGate.id` in `dsl/gunbc/ci.dag`.
    pub type CiGateId = String;

    /// Structural mirror of `CIGate` in `dsl/gunbc/ci.dag`.
    ///
    /// [`select_affected_gates`] consults only [`CiGateMeta::id`]. [`CiGateMeta::blocking`] is carried
    /// for **carrier parity** with the DSL record so runner-side dispatch can map rows without
    /// a forked struct; merge-blocking vs advisory semantics stay **outside** this selection substrate
    /// until a consumer reads the field.
    #[derive(Debug, Clone, PartialEq, Eq)]
    pub struct CiGateMeta {
        pub id: CiGateId,
        pub blocking: bool,
    }

    /// Structural mirror of `CIWorkflowDag`: gate roster + prerequisite edges.
    ///
    /// Each edge `(from, to)` means **`from` must complete before `to`** (matches
    /// `CIGateEdge { from, to }` in `ci.dag`).
    #[derive(Debug, Clone, Default, PartialEq, Eq)]
    pub struct CiWorkflowDagInput {
        pub gates: Vec<CiGateMeta>,
        /// Prerequisite edges: `from` runs before `to`.
        pub edges: Vec<(CiGateId, CiGateId)>,
    }

    // Practice 4 (coproduct checkpoint, `docs/modeling-discipline.md` §4):
    // 🟢 GREEN — terminal upstream-policy boundary for gate-id touch semantics before
    // `select_affected_gates`: `TouchAll` is the conservative in-DAG superset seed;
    // `TouchedGates` is the explicit finite set upstream mapped from lens/git facts.
    // Ledger: no third authority here — path-regex, env, and PR #2713 lens receipts stay
    // outside this module (Slice 7 brief + canvas §§1.1–4 end-state runner; Layer 1 only here).
    /// Diff-against-base input projected to **gate ids** (single authority at this boundary).
    #[derive(Debug, Clone, PartialEq, Eq)]
    pub enum CiWorkflowDiff {
        /// Every gate id in [`CiWorkflowDagInput::gates`] is treated as directly touched.
        TouchAll,
        /// Upstream bundle names gate ids with proven or assumed direct impact.
        TouchedGates(BTreeSet<CiGateId>),
    }

    // Practice 4 (coproduct checkpoint, `docs/modeling-discipline.md` §4):
    // 🟢 GREEN — terminal typed failure surface for [`select_affected_gates`]: malformed `CIWorkflowDag`
    // carrier vs non-acyclic directed prerequisites (full roster graph and/or selected subset; no silent success).
    // Ledger: (1) fact placement — not split across consumers; this `Result` boundary owns the `Err`
    // coproduct. (2) variant-is-data — rejected; payloads differ structurally. (3) algebraic — not
    // `std/` refs. (4) dimensional — not one decomposed axis space; each variant is an irreducible
    // outcome at the `dsl/gunbc/ci.dag` structural mirror until `.dag`-owned dispatch absorbs diagnostics.
    /// [`select_affected_gates`] failed: malformed `CIWorkflowDag` carrier or non-acyclic prerequisites.
    #[derive(Debug, Clone, PartialEq, Eq)]
    pub enum CiAffectedGatesError {
        /// The same `CIGate.id` appears more than once in [`CiWorkflowDagInput::gates`] (malformed carrier; must not collapse into a `HashSet` silently).
        DuplicateGateRosterId { id: CiGateId },
        /// `CIGateEdge` names a gate id not present in [`CiWorkflowDagInput::gates`] (violates single roster authority in `dsl/gunbc/ci.dag`).
        UnknownEdgeEndpoint { from: CiGateId, to: CiGateId },
        /// The directed prerequisite graph is not a DAG: either the **full** roster graph from
        /// [`CiWorkflowDagInput::edges`] contains a cycle, or the selected vertex set’s induced subgraph
        /// does (broken indegree accounting).
        NonAcyclicPrerequisiteGraph,
    }

    /// On success, returns gate ids to execute: the **connected component** of the seed under the symmetric
    /// closure of prerequisite edges (iterate `from ↔ to` adjacency to fixpoint), then
    /// **topologically sorted** on the directed subgraph (prerequisites first).
    ///
    /// **Fail-closed** (`design-t-wad-slice-7-binary-shim-affected-set-selection-canvas.md` §3):
    /// any touched id not present in `dag.gates` forces **all** gates listed in `dag.gates`
    /// into the plan (superset within this DAG).
    ///
    /// **Empty diff** (`TouchedGates` empty): returns `Ok` of an **empty** plan — callers map that
    /// to “no merge-blocking re-verify” vs “full superset” per repository policy **outside**
    /// this function (this module does not read policy carriers).
    ///
    /// **Malformed carrier:** duplicate [`CiGateMeta::id`] values in [`CiWorkflowDagInput::gates`]
    /// yield [`CiAffectedGatesError::DuplicateGateRosterId`] (roster must be unique before any `HashSet`
    /// view so gates are not dropped silently). Any edge whose `from` or `to` is absent from that roster
    /// yields [`CiAffectedGatesError::UnknownEdgeEndpoint`]. Any directed cycle in the **full**
    /// prerequisite graph on the roster (not only the touch-selected component) yields
    /// [`CiAffectedGatesError::NonAcyclicPrerequisiteGraph`] instead of returning `Ok` in narrow mode.
    pub fn select_affected_gates(
        dag: &CiWorkflowDagInput,
        diff: &CiWorkflowDiff,
    ) -> Result<Vec<CiGateId>, CiAffectedGatesError> {
        validate_unique_gate_roster(dag)?;
        let known: HashSet<&str> = dag.gates.iter().map(|g| g.id.as_str()).collect();
        for (from, to) in &dag.edges {
            if !known.contains(from.as_str()) || !known.contains(to.as_str()) {
                return Err(CiAffectedGatesError::UnknownEdgeEndpoint {
                    from: from.clone(),
                    to: to.clone(),
                });
            }
        }

        // Fail-closed on the whole carrier: a cycle in an unselected component must not yield `Ok`
        // for a disjoint touch seed (codex / P3).
        topo_sort_subset(dag, &known)?;

        let force_superset = match diff {
            CiWorkflowDiff::TouchAll => false,
            CiWorkflowDiff::TouchedGates(ids) => ids.iter().any(|id| !known.contains(id.as_str())),
        };

        let seed: HashSet<&str> = if force_superset {
            known.clone()
        } else {
            match diff {
                CiWorkflowDiff::TouchAll => known.clone(),
                CiWorkflowDiff::TouchedGates(ids) => ids.iter().map(|s| s.as_str()).collect(),
            }
        };

        if seed.is_empty() {
            return Ok(Vec::new());
        }

        // Symmetric edge closure: expand along `from ↔ to` until stable, then topo-sort
        // the induced set on directed prerequisite edges.
        let mut selected: HashSet<&str> = seed.clone();
        loop {
            let before = selected.len();
            for (from, to) in &dag.edges {
                let from = from.as_str();
                let to = to.as_str();
                if selected.contains(from) {
                    selected.insert(to);
                }
                if selected.contains(to) {
                    selected.insert(from);
                }
            }
            if selected.len() == before {
                break;
            }
        }

        topo_sort_subset(dag, &selected)
    }

    fn validate_unique_gate_roster(dag: &CiWorkflowDagInput) -> Result<(), CiAffectedGatesError> {
        let mut seen: HashSet<&str> = HashSet::new();
        for g in &dag.gates {
            if !seen.insert(g.id.as_str()) {
                return Err(CiAffectedGatesError::DuplicateGateRosterId { id: g.id.clone() });
            }
        }
        Ok(())
    }

    /// Set inclusion witness for ratchet tests.
    ///
    /// Returns whether `select_affected_gates(dag, narrow)` ⊆ `select_affected_gates(dag, wide)` as sets
    /// when **both** calls succeed; if either returns `Err`, returns `false`.
    /// Intended use: both arguments are [`CiWorkflowDiff::TouchedGates`] with `narrow_ids ⊆ wide_ids`, or
    /// `wide` is [`CiWorkflowDiff::TouchAll`] (superset selection). Other pairings are not a refinement
    /// partial order and may return `false` even when both plans are individually valid.
    pub fn selection_subset_under_touch_set_growth(
        dag: &CiWorkflowDagInput,
        narrow: &CiWorkflowDiff,
        wide: &CiWorkflowDiff,
    ) -> bool {
        match (
            select_affected_gates(dag, narrow),
            select_affected_gates(dag, wide),
        ) {
            (Ok(a), Ok(b)) => {
                let a: BTreeSet<_> = a.into_iter().collect();
                let b: BTreeSet<_> = b.into_iter().collect();
                a.is_subset(&b)
            }
            _ => false,
        }
    }

    /// **Layer 1** gate-id touch seed for [`select_affected_gates_for_binary_shim`].
    ///
    /// Canvas `design-t-wad-slice-7-binary-shim-affected-set-selection-canvas.md` §1.1
    /// steps 3–5 and §4 require the **runner** to consume PR #2713 structured output, join
    /// it with `CIWorkflowDag` / `TestClaim` metadata, and **then** emit executable work.
    /// This struct is **not** that receipt: it only carries `CIGate.id` strings (and a
    /// narrowing flag) **after** any `NodeRef` → gate-id mapping has happened elsewhere.
    ///
    /// When `narrowing_available` is `false`, selection fails closed to the full gate
    /// roster ([`CiWorkflowDiff::TouchAll`]; canvas §3: unknown dimension / missing
    /// receipt / unbuildable DAG pair).
    #[derive(Debug, Clone, PartialEq, Eq, Default)]
    pub struct CiBinaryShimAffectedSetReceipt {
        /// `false` forces [`CiWorkflowDiff::TouchAll`] regardless of `proven_direct_gate_touches`.
        pub narrowing_available: bool,
        /// Gate ids proven directly touched **after** upstream mapping (seed before symmetric expansion).
        pub proven_direct_gate_touches: BTreeSet<CiGateId>,
    }

    /// Layer 1 entry: map a **gate-id-only** [`CiBinaryShimAffectedSetReceipt`] into [`select_affected_gates`].
    pub fn select_affected_gates_for_binary_shim(
        dag: &CiWorkflowDagInput,
        receipt: &CiBinaryShimAffectedSetReceipt,
    ) -> Result<Vec<CiGateId>, CiAffectedGatesError> {
        let diff = if receipt.narrowing_available {
            CiWorkflowDiff::TouchedGates(receipt.proven_direct_gate_touches.clone())
        } else {
            CiWorkflowDiff::TouchAll
        };
        select_affected_gates(dag, &diff)
    }

    fn topo_sort_subset(
        dag: &CiWorkflowDagInput,
        subset: &HashSet<&str>,
    ) -> Result<Vec<CiGateId>, CiAffectedGatesError> {
        let mut indegree: HashMap<&str, usize> = HashMap::new();
        for id in subset.iter().copied() {
            indegree.entry(id).or_insert(0);
        }
        for (from, to) in &dag.edges {
            let from = from.as_str();
            let to = to.as_str();
            if subset.contains(from) && subset.contains(to) {
                *indegree.entry(to).or_insert(0) += 1;
            }
        }

        let mut queue: VecDeque<&str> = indegree
            .iter()
            .filter(|(_, d)| **d == 0)
            .map(|(n, _)| *n)
            .collect::<BTreeSet<_>>()
            .into_iter()
            .collect();

        let mut out: Vec<CiGateId> = Vec::new();
        while let Some(n) = queue.pop_front() {
            out.push(n.to_string());
            for (from, to) in &dag.edges {
                if from.as_str() != n {
                    continue;
                }
                let to = to.as_str();
                if !subset.contains(to) {
                    continue;
                }
                if let Some(d) = indegree.get_mut(to) {
                    *d -= 1;
                    if *d == 0 {
                        queue.push_back(to);
                    }
                }
            }
        }

        if out.len() != subset.len() {
            return Err(CiAffectedGatesError::NonAcyclicPrerequisiteGraph);
        }
        Ok(out)
    }

    #[cfg(test)]
    mod tests {
        use super::*;

        fn demo_ci_dag() -> CiWorkflowDagInput {
            CiWorkflowDagInput {
                gates: vec![
                    CiGateMeta {
                        id: "compile-gates".into(),
                        blocking: true,
                    },
                    CiGateMeta {
                        id: "lint".into(),
                        blocking: true,
                    },
                    CiGateMeta {
                        id: "tests".into(),
                        blocking: true,
                    },
                    CiGateMeta {
                        id: "l1-ratchet".into(),
                        blocking: true,
                    },
                ],
                edges: vec![
                    ("compile-gates".into(), "lint".into()),
                    ("compile-gates".into(), "tests".into()),
                    ("lint".into(), "l1-ratchet".into()),
                    ("tests".into(), "l1-ratchet".into()),
                ],
            }
        }

        #[test]
        fn select_affected_gates_empty_diff_returns_empty_plan() {
            let dag = demo_ci_dag();
            let diff = CiWorkflowDiff::TouchedGates(BTreeSet::new());
            assert_eq!(select_affected_gates(&dag, &diff), Ok(Vec::new()));
        }

        #[test]
        fn select_affected_gates_touch_all_runs_full_dag_in_topo_order() {
            let dag = demo_ci_dag();
            let got =
                select_affected_gates(&dag, &CiWorkflowDiff::TouchAll).expect("demo dag is valid");
            assert_eq!(
                got,
                vec![
                    "compile-gates".to_string(),
                    "lint".to_string(),
                    "tests".to_string(),
                    "l1-ratchet".to_string(),
                ]
            );
        }

        #[test]
        fn select_affected_gates_isolated_gate_no_edges() {
            let dag = CiWorkflowDagInput {
                gates: vec![CiGateMeta {
                    id: "solo".into(),
                    blocking: true,
                }],
                edges: vec![],
            };
            let diff = CiWorkflowDiff::TouchedGates(BTreeSet::from(["solo".into()]));
            assert_eq!(
                select_affected_gates(&dag, &diff),
                Ok(vec!["solo".to_string()])
            );
        }

        #[test]
        fn select_affected_gates_unknown_touch_id_forces_superset() {
            let dag = demo_ci_dag();
            let diff = CiWorkflowDiff::TouchedGates(BTreeSet::from(["no-such-gate".into()]));
            let got = select_affected_gates(&dag, &diff).expect("superset path is acyclic");
            let expect = select_affected_gates(&dag, &CiWorkflowDiff::TouchAll).expect("demo dag");
            assert_eq!(got, expect);
        }

        #[test]
        fn select_affected_gates_rejects_unknown_edge_endpoint() {
            let dag = CiWorkflowDagInput {
                gates: vec![CiGateMeta {
                    id: "solo".into(),
                    blocking: true,
                }],
                edges: vec![("solo".into(), "phantom".into())],
            };
            let diff = CiWorkflowDiff::TouchedGates(BTreeSet::from(["solo".into()]));
            assert_eq!(
                select_affected_gates(&dag, &diff),
                Err(CiAffectedGatesError::UnknownEdgeEndpoint {
                    from: "solo".into(),
                    to: "phantom".into(),
                })
            );
        }

        #[test]
        fn select_affected_gates_rejects_duplicate_gate_roster_ids() {
            let dag = CiWorkflowDagInput {
                gates: vec![
                    CiGateMeta {
                        id: "dup".into(),
                        blocking: true,
                    },
                    CiGateMeta {
                        id: "dup".into(),
                        blocking: false,
                    },
                ],
                edges: vec![],
            };
            assert_eq!(
                select_affected_gates(&dag, &CiWorkflowDiff::TouchAll),
                Err(CiAffectedGatesError::DuplicateGateRosterId { id: "dup".into() })
            );
        }

        #[test]
        fn select_affected_gates_rejects_prerequisite_cycle() {
            let dag = CiWorkflowDagInput {
                gates: vec![
                    CiGateMeta {
                        id: "a".into(),
                        blocking: true,
                    },
                    CiGateMeta {
                        id: "b".into(),
                        blocking: true,
                    },
                ],
                edges: vec![("a".into(), "b".into()), ("b".into(), "a".into())],
            };
            assert_eq!(
                select_affected_gates(&dag, &CiWorkflowDiff::TouchAll),
                Err(CiAffectedGatesError::NonAcyclicPrerequisiteGraph)
            );
        }

        #[test]
        fn select_affected_gates_rejects_global_cycle_even_when_touch_isolated() {
            let dag = CiWorkflowDagInput {
                gates: vec![
                    CiGateMeta {
                        id: "a".into(),
                        blocking: true,
                    },
                    CiGateMeta {
                        id: "b".into(),
                        blocking: true,
                    },
                    CiGateMeta {
                        id: "c".into(),
                        blocking: true,
                    },
                ],
                edges: vec![("a".into(), "b".into()), ("b".into(), "a".into())],
            };
            let diff = CiWorkflowDiff::TouchedGates(BTreeSet::from(["c".into()]));
            assert_eq!(
                select_affected_gates(&dag, &diff),
                Err(CiAffectedGatesError::NonAcyclicPrerequisiteGraph)
            );
        }

        #[test]
        fn select_affected_gates_empty_touch_rejects_when_global_graph_has_cycle() {
            let dag = CiWorkflowDagInput {
                gates: vec![
                    CiGateMeta {
                        id: "a".into(),
                        blocking: true,
                    },
                    CiGateMeta {
                        id: "b".into(),
                        blocking: true,
                    },
                ],
                edges: vec![("a".into(), "b".into()), ("b".into(), "a".into())],
            };
            let diff = CiWorkflowDiff::TouchedGates(BTreeSet::new());
            assert_eq!(
                select_affected_gates(&dag, &diff),
                Err(CiAffectedGatesError::NonAcyclicPrerequisiteGraph)
            );
        }

        #[test]
        fn select_affected_gates_lint_only_pulls_l1_and_shared_prereqs() {
            let dag = demo_ci_dag();
            let diff = CiWorkflowDiff::TouchedGates(BTreeSet::from(["lint".into()]));
            let got = select_affected_gates(&dag, &diff).expect("demo dag");
            let set: BTreeSet<_> = got.iter().cloned().collect();
            assert_eq!(
                set,
                BTreeSet::from([
                    "compile-gates".into(),
                    "lint".into(),
                    "tests".into(),
                    "l1-ratchet".into(),
                ])
            );
            assert_eq!(got.first().map(String::as_str), Some("compile-gates"));
        }

        #[test]
        fn selection_subset_under_touch_set_growth_holds_on_demo_dag() {
            let dag = demo_ci_dag();
            let narrow = CiWorkflowDiff::TouchedGates(BTreeSet::from(["lint".into()]));
            let wide =
                CiWorkflowDiff::TouchedGates(BTreeSet::from(["lint".into(), "tests".into()]));
            assert!(selection_subset_under_touch_set_growth(
                &dag, &narrow, &wide
            ));
        }

        #[test]
        fn selection_subset_empty_diff_is_subset_of_nonempty() {
            let dag = demo_ci_dag();
            let empty = CiWorkflowDiff::TouchedGates(BTreeSet::new());
            let wide = CiWorkflowDiff::TouchedGates(BTreeSet::from(["tests".into()]));
            assert!(selection_subset_under_touch_set_growth(&dag, &empty, &wide));
        }

        #[test]
        fn binary_shim_receipt_unknown_narrowing_matches_touch_all() {
            let dag = demo_ci_dag();
            let receipt = CiBinaryShimAffectedSetReceipt {
                narrowing_available: false,
                proven_direct_gate_touches: BTreeSet::from(["lint".into()]),
            };
            let got = select_affected_gates_for_binary_shim(&dag, &receipt).expect("valid dag");
            let expect = select_affected_gates(&dag, &CiWorkflowDiff::TouchAll).expect("valid dag");
            assert_eq!(got, expect);
        }

        #[test]
        fn binary_shim_receipt_narrow_lint_matches_touched_gates_lint() {
            let dag = demo_ci_dag();
            let receipt = CiBinaryShimAffectedSetReceipt {
                narrowing_available: true,
                proven_direct_gate_touches: BTreeSet::from(["lint".into()]),
            };
            let got = select_affected_gates_for_binary_shim(&dag, &receipt).expect("valid dag");
            let expect = select_affected_gates(
                &dag,
                &CiWorkflowDiff::TouchedGates(BTreeSet::from(["lint".into()])),
            )
            .expect("valid dag");
            assert_eq!(got, expect);
        }

        #[test]
        fn binary_shim_receipt_empty_narrow_seed_yields_empty_plan() {
            let dag = demo_ci_dag();
            let receipt = CiBinaryShimAffectedSetReceipt {
                narrowing_available: true,
                proven_direct_gate_touches: BTreeSet::new(),
            };
            assert_eq!(
                select_affected_gates_for_binary_shim(&dag, &receipt),
                Ok(Vec::new())
            );
        }
    }
}

use self::integration_rs_wiring_scan::integration_rs_cementing_path_attr_binds_mod_stem;
use self::r3_gate_87_cementing_regen_runner_suites::r3_gate_87_cementing_regen_pb_b1_dag_module_stems;
use std::collections::{BTreeSet, HashSet};
use std::path::Path as FsPath;

use crate::dag::{Dag, FieldValue, LiteralBits, TypeConnective, ValueBody};

fn record_field<'a>(fields: &'a [(String, FieldValue)], label: &str) -> Option<&'a FieldValue> {
    fields
        .iter()
        .find(|(candidate, _)| candidate == label)
        .map(|(_, value)| value)
}

fn string_field(fields: &[(String, FieldValue)], label: &str) -> Result<String, String> {
    match record_field(fields, label) {
        Some(FieldValue::Literal(LiteralBits::String(value))) => Ok(value.clone()),
        Some(other) => Err(format!("`{label}` must be a string literal, got {other:?}")),
        None => Err(format!("record is missing string field `{label}`")),
    }
}

fn disj_variants(
    dag: &Dag,
    type_name: &str,
) -> Result<Vec<(String, crate::dag::DeclarationId)>, String> {
    let sum_decl = dag.declaration_by_name(type_name).ok_or_else(|| {
        format!(
            "merged DAG missing nullary sum `{type_name}` — expected `std.verification` for lens \
             capability axes, or `tests/dag/cementing_dispatch.dag` for `CementingBandCReceiptKind`"
        )
    })?;
    let TypeConnective::Disj { variants } = &sum_decl.connective else {
        return Err(format!("`{type_name}` must be a Disj coproduct"));
    };
    Ok(variants.iter().map(|v| (v.label.clone(), v.ty)).collect())
}

fn decode_nullary_sum_variant(
    dag: &Dag,
    sum_type_name: &str,
    value: &FieldValue,
    field_label: &str,
    record_role: &str,
) -> Result<String, String> {
    let variants = disj_variants(dag, sum_type_name)?;
    let allowed: HashSet<crate::dag::DeclarationId> = variants.iter().map(|(_, id)| *id).collect();
    let FieldValue::Variant {
        constructor,
        payload,
    } = value
    else {
        return Err(format!(
            "{record_role} `{field_label}` must be a closed sum variant of `{sum_type_name}`; got {value:?}"
        ));
    };
    if !payload.is_empty() {
        return Err(format!(
            "{record_role} `{field_label}`: unexpected variant payload (expected nullary `{sum_type_name}` arm)"
        ));
    }
    if !allowed.contains(constructor) {
        return Err(format!(
            "{record_role} `{field_label}`: constructor id {:?} is not a declared variant of `{sum_type_name}`",
            constructor
        ));
    }
    variants
        .iter()
        .find(|(_, id)| id == constructor)
        .map(|(label, _)| label.clone())
        .ok_or_else(|| {
            format!(
                "{record_role} `{field_label}`: internal mismatch resolving `{sum_type_name}` variant"
            )
        })
}

/// Maps `CementingBandCReceiptKind` variant labels to the stable wire tags used in
/// `expected_cementing_receipt_triples` and on-disk dispatch branches.
fn cementing_receipt_kind_wire_tag(sum_variant_label: &str) -> Result<&'static str, String> {
    match sum_variant_label {
        "DagHarness" => Ok("dag"),
        "TemporaryRustModule" => Ok("temporary-rust"),
        other => Err(format!(
            "cementing receipt `kind`: unknown `CementingBandCReceiptKind` variant `{other}`"
        )),
    }
}

fn decode_cementing_band_c_receipt_kind(
    dag: &Dag,
    value: &FieldValue,
    field_label: &str,
) -> Result<&'static str, String> {
    let label = decode_nullary_sum_variant(
        dag,
        "CementingBandCReceiptKind",
        value,
        field_label,
        "cementing receipt row",
    )?;
    cementing_receipt_kind_wire_tag(&label)
}

fn record_fields(value: &FieldValue) -> Option<&[(String, FieldValue)]> {
    match value {
        FieldValue::Record(fields) => Some(fields.as_slice()),
        _ => None,
    }
}

fn resolve_declaration_ref_id(
    value: &FieldValue,
    field_label: &str,
) -> Result<crate::dag::DeclarationId, String> {
    match value {
        FieldValue::Reference(id) => Ok(*id),
        FieldValue::Record(fields) if fields.is_empty() => Err(format!(
            "`{field_label}`: DeclarationRef is the empty record literal {{}} — use an identifier \
             so lowering emits FieldValue::Reference(DeclarationId), not an empty record",
        )),
        other => Err(format!(
            "`{field_label}`: expected FieldValue::Reference(DeclarationId) \
             for a DeclarationRef edge, got {other:?}"
        )),
    }
}

fn list_items_of_declaration(
    dag: &Dag,
    id: crate::dag::DeclarationId,
    role: &str,
) -> Result<Vec<FieldValue>, String> {
    let decl = dag.declaration(id);
    match &decl.value_body {
        Some(ValueBody::List(items)) => Ok(items.clone()),
        other => Err(format!(
            "`{role}` must resolve to a `List<…>` data declaration; got {:?} for `{}`",
            other,
            decl.name.as_deref().unwrap_or("<anonymous>")
        )),
    }
}

fn read_lens_registry_name_lens_file_pairs(dag: &Dag) -> Result<Vec<(String, String)>, String> {
    let entry_type_id = dag
        .declaration_by_name("LensRegistryEntry")
        .map(|decl| decl.id)
        .ok_or_else(|| "bootstrap must declare `LensRegistryEntry` (regen.dag)".to_string())?;

    let mut pairs = Vec::new();
    for decl in dag.declarations() {
        if decl.meta_tag != Some(entry_type_id) {
            continue;
        }
        let Some(ValueBody::Structural { fields }) = &decl.value_body else {
            return Err(format!(
                "lens registry entry `{}` must carry a structural value body",
                decl.name.as_deref().unwrap_or("<anonymous>")
            ));
        };
        let binding = decl
            .name
            .clone()
            .unwrap_or_else(|| "<anonymous>".to_string());
        pairs.push((
            string_field(fields, "name")
                .map_err(|e| format!("lens registry entry `{binding}`: {e}"))?,
            string_field(fields, "lens_file")
                .map_err(|e| format!("lens registry entry `{binding}`: {e}"))?,
        ));
    }
    Ok(pairs)
}

/// Closed roster of Band-C `(registry_name, module_stem, kind)` receipts implied by the
/// current `regen.dag` × v2-complete register projection. When a new v2-complete lens
/// lands in `regen.dag`, extend this expansion in the same PR as `cementing_dispatch.dag`
/// receipt rows — otherwise the dispatch predicate fail-closes with an explicit error.
fn expected_cementing_receipt_triples(
    registry_pairs: &[(String, String)],
    basenames: &BTreeSet<String>,
) -> Result<BTreeSet<(String, String, String)>, String> {
    let mut out = BTreeSet::new();
    for (name, lens_file) in registry_pairs {
        let basename = FsPath::new(lens_file)
            .file_name()
            .and_then(|s| s.to_str())
            .ok_or_else(|| {
                format!("registry entry `{name}` has lens_file without basename: {lens_file}")
            })?
            .to_string();
        if !basenames.contains(&basename) {
            continue;
        }
        match (name.as_str(), basename.as_str()) {
            ("cost", "complexity.dag") => {
                out.insert((
                    name.clone(),
                    "t_r3_gate_87_cementing_regen_cost".to_string(),
                    "dag".to_string(),
                ));
                out.insert((
                    name.clone(),
                    "complexity_lens_behavioral_completion".to_string(),
                    "temporary-rust".to_string(),
                ));
            }
            ("cost_symbolic", "cost.dag") => {
                out.insert((
                    name.clone(),
                    "t_r3_gate_87_cementing_regen_cost_symbolic".to_string(),
                    "dag".to_string(),
                ));
                out.insert((
                    name.clone(),
                    "cost_lens_symbolic_consumer_test".to_string(),
                    "temporary-rust".to_string(),
                ));
            }
            _ => {
                return Err(format!(
                    "Band-C v2 cementing projection includes `LensRegistryEntry` \
                     (`name={name}`, `lens_file` basename `{basename}`) but \
                     `expected_cementing_receipt_triples` has no receipt expansion — \
                     land matching `cementing_band_c_v2_complete_receipts` rows in \
                     `cementing_dispatch.dag` and extend the expansion table in \
                     `cementing_dispatch.rs` in the same PR."
                ));
            }
        }
    }
    Ok(out)
}

fn v2_cementing_basenames_from_capability_rows(
    dag: &Dag,
    capability_rows: &[FieldValue],
) -> Result<BTreeSet<String>, String> {
    let mut basenames = BTreeSet::new();
    for row in capability_rows {
        let Some(fields) = record_fields(row) else {
            return Err(format!(
                "capability_register list: expected record row, got {row:?}"
            ));
        };
        let lens_basename = string_field(fields, "lens_basename")?;
        let structural = record_field(fields, "structural").ok_or_else(|| {
            "capability_register row: missing `structural` field (expected \
             `LensCapabilityStructuralStatus` variant)"
                .to_string()
        })?;
        let behavioral = record_field(fields, "behavioral").ok_or_else(|| {
            "capability_register row: missing `behavioral` field (expected \
             `LensCapabilityBehavioralStatus` variant)"
                .to_string()
        })?;
        let v2 = record_field(fields, "v2_counterpart").ok_or_else(|| {
            "capability_register row: missing `v2_counterpart` field (expected \
             `LensCapabilityV2Counterpart` variant)"
                .to_string()
        })?;
        decode_nullary_sum_variant(
            dag,
            "LensCapabilityStructuralStatus",
            structural,
            "structural",
            "capability_register row",
        )?;
        let behavioral_label = decode_nullary_sum_variant(
            dag,
            "LensCapabilityBehavioralStatus",
            behavioral,
            "behavioral",
            "capability_register row",
        )?;
        let v2_label = decode_nullary_sum_variant(
            dag,
            "LensCapabilityV2Counterpart",
            v2,
            "v2_counterpart",
            "capability_register row",
        )?;
        if behavioral_label == "LensCapabilityBehavioralComplete"
            && v2_label == "LensCapabilityV2RealV2"
        {
            basenames.insert(lens_basename);
        }
    }
    Ok(basenames)
}

/// Lens basenames that participate in Band-C v2 cementing: `LensCapabilityBehavioralComplete`
/// plus `LensCapabilityV2RealV2` in the canonical `std.verification` `lens_capability_register_rows`
/// list (same projection `CementingDispatchMatchesProjection` uses before intersecting `regen.dag`).
///
/// Exposed for integration tests that mechanically ratchet the markdown capability table against
/// this structural authority (`lens_register_correspondence_test`).
pub fn lens_capability_register_v2_cementing_basenames(
    dag: &Dag,
) -> Result<BTreeSet<String>, String> {
    let reg_decl = dag
        .declaration_by_name("lens_capability_register_rows")
        .ok_or_else(|| {
            "bootstrap must declare `lens_capability_register_rows` (std.verification)".to_string()
        })?;
    let capability_rows =
        list_items_of_declaration(dag, reg_decl.id, "lens_capability_register_rows")?;
    v2_cementing_basenames_from_capability_rows(dag, &capability_rows)
}

fn cementing_dispatch_two_refs(
    payload: &[FieldValue],
) -> Result<(&FieldValue, &FieldValue), String> {
    match payload {
        [a, b] => Ok((a, b)),
        [FieldValue::Record(fields)] => {
            let a = record_field(fields, "capability_register").ok_or_else(|| {
                "CementingDispatchMatchesProjection record missing `capability_register`"
                    .to_string()
            })?;
            let b = record_field(fields, "cementing_receipts").ok_or_else(|| {
                "CementingDispatchMatchesProjection record missing `cementing_receipts`".to_string()
            })?;
            Ok((a, b))
        }
        _ => Err(format!(
            "CementingDispatchMatchesProjection payload should be two DeclarationRef edges \
             or a record {{ capability_register, cementing_receipts }}; got {} slot(s)",
            payload.len()
        )),
    }
}

/// Evaluate `CementingDispatchMatchesProjection` for a claim declared in `declaration_file`.
///
/// Returns `Ok(())` on pass; `Err(reason)` maps to [`crate::test_runner::ClaimResult::Fail`].
pub(crate) fn evaluate_cementing_dispatch_projection(
    dag: &Dag,
    declaration_file: &str,
    payload: &[FieldValue],
) -> Result<(), String> {
    const CEMENTING_DISPATCH_DECL_PATH: &str = "cementing_dispatch.dag";
    if !declaration_file.ends_with(CEMENTING_DISPATCH_DECL_PATH) {
        return Err(format!(
            "CementingDispatchMatchesProjection is only accepted for claims declared in `**/{CEMENTING_DISPATCH_DECL_PATH}`; got `{declaration_file}`"
        ));
    }

    let (reg_ref, recv_ref) = cementing_dispatch_two_refs(payload)?;
    let reg_id = resolve_declaration_ref_id(reg_ref, "capability_register")?;
    let recv_id = resolve_declaration_ref_id(recv_ref, "cementing_receipts")?;

    let capability_rows = list_items_of_declaration(dag, reg_id, "capability_register")?;
    let receipt_rows = list_items_of_declaration(dag, recv_id, "cementing_receipts")?;

    let basenames = v2_cementing_basenames_from_capability_rows(dag, &capability_rows)?;

    let registry_pairs = read_lens_registry_name_lens_file_pairs(dag)?;

    let mut matched_basenames = BTreeSet::new();
    for (name, lens_file) in &registry_pairs {
        let Some(basename) = FsPath::new(lens_file).file_name().and_then(|s| s.to_str()) else {
            return Err(format!(
                "registry entry `{name}` has lens_file without basename: {lens_file}"
            ));
        };
        if basenames.contains(basename) {
            matched_basenames.insert(basename.to_string());
        }
    }

    let missing: Vec<_> = basenames.difference(&matched_basenames).cloned().collect();
    if !missing.is_empty() {
        return Err(format!(
            "`lens_capability_register` escalates v2 cementing for lens basenames {missing:?}, \
             but no `LensRegistryEntry` in bootstrap names those files — fix the register data or add registry entries."
        ));
    }

    let mut receipt_triples = BTreeSet::new();

    for row in &receipt_rows {
        let Some(fields) = record_fields(row) else {
            return Err(format!(
                "cementing_receipts list: expected record row, got {row:?}"
            ));
        };
        let registry_name = string_field(fields, "registry_name")?;
        let module_stem = string_field(fields, "module_stem")?;
        let kind_field = record_field(fields, "kind").ok_or_else(|| {
            "cementing receipt row: missing `kind` field (expected `CementingBandCReceiptKind` \
             variant)"
                .to_string()
        })?;
        let kind_str = decode_cementing_band_c_receipt_kind(dag, kind_field, "kind")?;
        let triple = (
            registry_name.clone(),
            module_stem.clone(),
            kind_str.to_string(),
        );
        if !receipt_triples.insert(triple.clone()) {
            return Err(format!(
                "cementing_receipts contains duplicate receipt identity {triple:?}; each \
                 `(registry_name, module_stem, kind)` must be unique."
            ));
        }
    }

    let expected_triples = expected_cementing_receipt_triples(&registry_pairs, &basenames)?;
    if receipt_triples != expected_triples {
        return Err(format!(
            "cementing_receipts `(registry_name, module_stem, kind)` triples must exactly match \
             the Band-C expansion of the register ∩ regen projection — expected {expected_triples:?}, \
             got {receipt_triples:?}"
        ));
    }

    let manifest_dir = std::path::PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    let pb_b1_gate87_dag_stems = r3_gate_87_cementing_regen_pb_b1_dag_module_stems();
    let integration_rs = match std::fs::read_to_string(manifest_dir.join("tests/integration.rs")) {
        Ok(text) => text,
        Err(err) => {
            return Err(format!(
                "read tests/integration.rs for cementing wiring ratchet: {err}"
            ));
        }
    };

    for row in &receipt_rows {
        let Some(fields) = record_fields(row) else {
            return Err(format!(
                "cementing_receipts list: expected record row, got {row:?}"
            ));
        };
        let registry_name = string_field(fields, "registry_name")?;
        let module_stem = string_field(fields, "module_stem")?;
        let kind_field = record_field(fields, "kind").ok_or_else(|| {
            "cementing receipt row: missing `kind` field (expected `CementingBandCReceiptKind` \
             variant)"
                .to_string()
        })?;
        let kind_str = decode_cementing_band_c_receipt_kind(dag, kind_field, "kind")?;
        match kind_str {
            "dag" => {
                if !pb_b1_gate87_dag_stems.contains(&module_stem) {
                    return Err(format!(
                        "registry lens `{registry_name}` lists v2-complete cementing receipt `{module_stem}` \
                         as a `.dag` harness, but that stem is not wired in \
                         `r3_gate_87_cementing_regen_runner_suites::R3_GATE_87_CEMENTING_REGEN_SUITES` \
                         (T-PB-B-1 runner) — extend the shared table or fix the receipt list."
                    ));
                }
                let path = manifest_dir
                    .join("tests")
                    .join("dag")
                    .join(format!("{module_stem}.dag"));
                if !path.is_file() {
                    return Err(format!(
                        "registry lens `{registry_name}` lists v2-complete cementing receipt `{module_stem}` \
                         as a `.dag` harness; expected file {}",
                        path.display()
                    ));
                }
            }
            "temporary-rust" => {
                let path = manifest_dir
                    .join("tests")
                    .join("integration")
                    .join("cementing")
                    .join(format!("{module_stem}.rs"));
                if !path.is_file() {
                    return Err(format!(
                        "registry lens `{registry_name}` lists temporary Rust cementing receipt `{module_stem}`; \
                         expected file {}",
                        path.display()
                    ));
                }
                if !integration_rs_cementing_path_attr_binds_mod_stem(
                    &integration_rs,
                    &module_stem,
                )? {
                    let expected = format!(r#"#[path = "integration/cementing/{module_stem}.rs"]"#);
                    return Err(format!(
                        "registry lens `{registry_name}` lists temporary Rust cementing stem `{module_stem}` but \
                         tests/integration.rs does not bind `{expected}` to `mod {module_stem};` in the same item \
                         (Band-C dispatch)."
                    ));
                }
            }
            _ => {
                return Err(
                    "cementing receipt `kind`: internal error — wire tag not `dag` or `temporary-rust`"
                        .to_string(),
                );
            }
        }
    }

    Ok(())
}
